send-request.set-body:
@{
      var requestBody = (string)context.Variables["ai-hub-request-body"];
      return new JObject(
        new JProperty("kind", "PiiEntityRecognition"),
        new JProperty("analysisInput", new JObject(
          new JProperty("documents", new JArray(new JObject(
            new JProperty("id", "request"),
            new JProperty("language", "{{ai-hub-pii-language}}"),
            new JProperty("text", requestBody)
          )))
        )),
        new JProperty("parameters", new JObject(
          new JProperty("modelVersion", "latest")
        ))
      ).ToString();
    }

when.condition:
@{
      var response = context.Variables.ContainsKey("ai-hub-pii-response")
        ? (IResponse)context.Variables["ai-hub-pii-response"]
        : null;
      return response == null || response.StatusCode != 200;
    }

@{
      var response = (IResponse)context.Variables["ai-hub-pii-response"];
      var result = response.Body.As<JObject>();
      var documents = result["results"]?["documents"] as JArray;
      return documents != null && documents.Any(document =>
        document["entities"] is JArray entities && entities.Count > 0);
    }
